{
  "summary": "The study included 74 women with O-RADS MRI score 4 adnexal masses, of which 55.4% were malignant. Malignant masses were distinguished from benign ones by various MRI and clinical features, including patient age, CA-125 levels, and the size of solid tissue. Inter-reader agreement for most features was excellent to good.",
  "findings": [
    {
      "statement": "The study involved 74 women with a median age of 52 years.",
      "claim_ids": [
        "cf6edbc31b00"
      ]
    },
    {
      "statement": "Based on pathology, 41 (55.4%) of the adnexal masses were malignant.",
      "claim_ids": [
        "bceaf0943b9d"
      ]
    },
    {
      "statement": "Malignant and benign O-RADS MRI score 4 adnexal masses were distinguished by various MRI and clinical features.",
      "claim_ids": [
        "815ca349b6d7"
      ]
    },
    {
      "statement": "Patients with malignant masses were younger and had higher CA-125 levels.",
      "claim_ids": [
        "2724f2845d97"
      ]
    },
    {
      "statement": "The size of solid tissue was larger in malignant masses.",
      "claim_ids": [
        "0b8cb84f6e61"
      ]
    },
    {
      "statement": "Inter-reader agreement for most features was excellent-good, with ICC values between 0.662 and 0.950 and k values between 0.650 and 0.860.",
      "claim_ids": [
        "060b7f72b87f"
      ]
    },
    {
      "statement": "Other imaging findings did not show significant differences, with p-values ranging from 0.09 to 0.77.",
      "claim_ids": [
        "f9f9dfd0fc78"
      ]
    }
  ]
}
